<script setup>
import {ref,onMounted} from 'vue'
import {api,download} from '../services/api.js'
import GlassWindow from './GlassWindow.vue'
const destinations=ref([]),scopes=ref([]),deliveries=ref({items:[],total:0}),page=ref(1),status=ref(''),error=ref(''),message=ref(''),busy=ref(false),open=ref(false),editId=ref(null),secret=ref('')
const empty=()=>({name:'',endpoint:'',scopeId:'default',enabled:false,intervalMinutes:1440,eventTypes:[]}),form=ref(empty())
async function load(){busy.value=true;error.value='';try{const [d,l]=await Promise.all([api('/evidence-destinations'),api('/evidence-deliveries?'+new URLSearchParams({page:page.value,pageSize:25,...(status.value?{status:status.value}:{})}))]);destinations.value=d;deliveries.value=l}catch(e){error.value=e.message}finally{busy.value=false}}
function edit(d){editId.value=d?.id||null;form.value=d?{name:d.name,endpoint:d.endpoint,scopeId:d.scopeId,enabled:d.enabled,intervalMinutes:d.intervalMinutes,eventTypes:[...d.eventTypes]}:empty();secret.value='';open.value=true}
async function save(){busy.value=true;error.value='';try{const d=await api('/evidence-destinations'+(editId.value?'/'+editId.value:''),{method:editId.value?'PUT':'POST',body:form.value});secret.value=d.oneTimeSecret||'';open.value=false;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function queue(d){busy.value=true;error.value='';try{await api(`/evidence-destinations/${d.id}/snapshot`,{method:'POST',body:{}});message.value='Snapshot queued. Delivery status updates after the next worker cycle.';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function retry(d){try{await api(`/evidence-deliveries/${d.id}/retry`,{method:'POST',body:{}});await load()}catch(e){error.value=e.message}}
async function exportSnapshot(){try{await download('/reports/evidence?'+new URLSearchParams({scopeId:form.value.scopeId}),'coverage-evidence.json')}catch(e){error.value=e.message}}
onMounted(async()=>{await load();try{scopes.value=await api('/inventory/scopes')}catch(e){error.value=e.message}})
</script>
<template><div class="evidence"><div class="actions"><button class="button secondary" :disabled="busy" @click="load">Refresh deliveries</button><button class="button primary" @click="edit()">Add evidence destination</button><label>Snapshot scope<select v-model="form.scopeId"><option v-for="s in scopes" :key="s.id" :value="s.id">{{s.name}}</option></select></label><button class="button secondary" @click="exportSnapshot">Download evidence</button></div><p v-if="error" class="error-msg" role="alert">{{error}}</p><p v-if="message" class="success-msg">{{message}}</p><p class="muted">Scheduled coverage snapshots and selected operational events go to your HTTPS receiver. Each delivery is signed and carries a stable ID for duplicate handling. Destinations start disabled.</p><div class="table-wrap"><table><thead><tr><th>Destination</th><th>Scope</th><th>Schedule</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="d in destinations" :key="d.id"><td>{{d.name}}<small>{{d.endpoint}}</small></td><td>{{d.scopeId}}</td><td>Every {{d.intervalMinutes}} minutes</td><td>{{d.enabled?'Enabled':'Disabled'}}<small v-if="d.lastError">{{d.lastError}}</small></td><td><button class="button small secondary" @click="edit(d)">Edit</button><button class="button small secondary" :disabled="busy||!d.enabled" @click="queue(d)">Queue snapshot</button></td></tr><tr v-if="!destinations.length"><td colspan="5">No evidence destinations configured.</td></tr></tbody></table></div><h3>Delivery history</h3><select v-model="status" aria-label="Evidence delivery status" @change="page=1;load()"><option value="">All statuses</option><option v-for="s in ['pending','sent','failed','cancelled']" :key="s">{{s}}</option></select><div class="table-wrap"><table><thead><tr><th>Delivery</th><th>Created</th><th>Status</th><th>Attempts</th><th>Result</th></tr></thead><tbody><tr v-for="d in deliveries.items" :key="d.id"><td>{{d.id}}<small>{{d.event_key}}</small></td><td>{{new Date(d.created_at).toLocaleString()}}</td><td>{{d.status}}</td><td>{{d.attempts}}</td><td>{{d.last_error||'—'}} <button v-if="d.status==='failed'" class="button small secondary" @click="retry(d)">Retry</button></td></tr><tr v-if="!deliveries.items.length"><td colspan="5">No deliveries.</td></tr></tbody></table></div><div class="actions"><span>{{deliveries.total}} deliveries · Page {{page}}</span><button class="button secondary" :disabled="busy||page===1" @click="page--;load()">Previous</button><button class="button secondary" :disabled="busy||page*25>=deliveries.total" @click="page++;load()">Next</button></div><GlassWindow v-model="open" :title="editId?'Edit evidence destination':'Add evidence destination'"><form class="form" @submit.prevent="save"><p v-if="error" class="error-msg">{{error}}</p><label>Name<input v-model.trim="form.name" required maxlength="120"></label><label>HTTPS receiver<input v-model.trim="form.endpoint" type="url" required placeholder="https://siem.example.com/winfire"></label><label>Inventory scope<select v-model="form.scopeId"><option v-for="s in scopes" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Interval in minutes<input v-model.number="form.intervalMinutes" type="number" min="15" max="10080" required></label><label>Operational events<select v-model="form.eventTypes" multiple><option v-for="t in ['policy','drift','containment','connector']" :key="t">{{t}}</option></select></label><label class="switch-field"><span>Enable scheduled delivery</span><input v-model="form.enabled" type="checkbox" role="switch"><span class="switch-control" aria-hidden="true"></span></label><p>Saving changes cancels older pending deliveries. Existing signing secrets remain unchanged.</p><button class="button primary" :disabled="busy">Save destination</button></form></GlassWindow><GlassWindow :model-value="!!secret" title="Copy webhook signing secret" @update:model-value="secret=''"><div class="form"><p>Store this secret in your receiver. It is shown once.</p><code class="secret">{{secret}}</code><button class="button primary" @click="secret=''">Done</button></div></GlassWindow></div></template>
<style scoped>.evidence{padding:16px;min-width:0}.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:16px 0}label{display:grid;gap:6px}.form{display:grid;gap:14px;padding:16px}.table-wrap{max-width:100%;overflow:auto}table{width:100%}td{max-width:45ch;overflow-wrap:anywhere}small{display:block;color:var(--muted)}.secret{white-space:pre-wrap;overflow-wrap:anywhere}</style>
